<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { CalendarDays, Laptop, Info, ArrowRight, Check } from 'lucide-vue-next'
import DateRangePicker from './DateRangePicker.vue'
import { useApi, refreshData } from '../composables/query'
import { post } from '../services/api'
import { isoDate, validateDates } from '../services/dates'
import { useSession } from '../stores/session'
import type { Lookup, WorkRequest } from '../types'
const props=defineProps<{kind:'LEAVE'|'MOBILE'}>()
const router=useRouter(), session=useSession(), types=useApi<Lookup[]>('/leave-types')
const form=reactive({kind:props.kind,start_date:'',end_date:'',portion:'FULL',leave_type_id:1,location_type:'HOME',city:'',country:'',comment:''})
const preview=ref<{days:string;exceptions:string[];years:{year:number;days:string;available:string|null}[]}|null>(null), error=ref(''), busy=ref(false), calculating=ref(false)
let generation=0
const valid=computed(()=>!validateDates(form.start_date,form.end_date,form.portion))
watch(()=>JSON.stringify(form),async()=>{preview.value=null;error.value='';const current=++generation;if(!valid.value)return;calculating.value=true;try{const value=await post<typeof preview.value>('/requests/preview',form);if(current===generation)preview.value=value}catch(e){if(current===generation)error.value=(e as Error).message}finally{if(current===generation)calculating.value=false}})
async function submit(draft=false){error.value=validateDates(form.start_date,form.end_date,form.portion);if(error.value)return;busy.value=true;try{await post<WorkRequest>('/requests',{...form,submit:!draft});await refreshData();session.message(draft?'Draft saved.':'Your request has been submitted.');router.push('/requests')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><form class="request-layout" @submit.prevent="submit()"><section class="panel form-panel"><div class="request-kind"><span class="icon-tile"><CalendarDays v-if="kind==='LEAVE'"/><Laptop v-else/></span><div><h2>{{kind==='LEAVE'?'Make room for a break':'Work from somewhere else'}}</h2><p class="muted">A few details, and we’ll take it from here.</p></div></div><label v-if="kind==='LEAVE'">Leave type<select v-model.number="form.leave_type_id"><option v-for="type in types.data.value" :key="type.id" :value="type.id">{{type.name}}</option></select></label><DateRangePicker v-model:start="form.start_date" v-model:end="form.end_date" :minimum="isoDate()"/><label>Duration<select v-model="form.portion"><option value="FULL">Full day</option><option value="AM">Half day · morning</option><option value="PM">Half day · afternoon</option></select></label><template v-if="kind==='MOBILE'"><label>Work location<select v-model="form.location_type"><option value="HOME">Home</option><option value="OTHER">Other location</option><option value="ABROAD">Abroad · HR review may be required</option></select></label><div v-if="form.location_type!=='HOME'" class="form-grid"><label>City<input v-model="form.city" required maxlength="120" placeholder="e.g. Sofia"></label><label>Country code<input v-model="form.country" required minlength="2" maxlength="2" placeholder="e.g. BG"></label></div></template><label>Note <span class="optional">optional · visible to your manager</span><textarea v-model="form.comment" rows="4" maxlength="1000" placeholder="Anything your manager should know?"/></label><p class="field-hint">Please don’t include medical details or other sensitive personal information.</p><div v-if="error" class="error-box" role="alert">{{error}}</div><div class="form-actions"><button class="btn secondary" type="button" :disabled="busy||!preview" @click="submit(true)">Save draft</button><button class="btn primary" type="submit" :disabled="busy||!preview||calculating">{{busy?'Submitting…':'Submit request'}}<ArrowRight :size="16"/></button></div></section><aside><section class="panel summary-panel"><span class="eyebrow">YOUR REQUEST AT A GLANCE</span><h2>{{calculating?'Calculating…':preview?`${preview.days} working days`:'Your next little reset'}}</h2><p class="muted">Your schedule and company holidays are taken into account automatically.</p><template v-if="preview"><div v-for="year in preview.years" :key="year.year" class="summary-line"><span>{{year.year}} · {{year.days}} days</span><strong v-if="year.available!==null">{{Number(year.available)-Number(year.days)}} left*</strong></div><p v-if="kind==='LEAVE'" class="field-hint">*Estimate at the first leave date. Final approval checks credit expiry and the available balance for each day.</p><div v-for="flag in preview.exceptions" :key="flag" class="notice"><Info :size="16"/>{{flag.replaceAll('_',' ')}} · HR review</div></template><div class="summary-divider"/><div class="check-line"><Check :size="16"/>Only scheduled workdays count</div><div class="check-line"><Check :size="16"/>Track progress in My requests</div><div class="check-line"><Check :size="16"/>We’ll notify you of the decision</div></section></aside></form></template>
